// Parse & Validate Input
const body = $input.item.json.body || {};

if (!body.instruction && !body.topic) {
  throw new Error('❌ Bitte gib eine Anweisung (instruction) oder ein Thema (topic) an!');
}

return {
  json: {
    user_instruction: body.instruction || `Schreibe einen umfassenden Blog über ${body.topic}`,
    custom_topic: body.topic || null,
    target_audience: body.audience || null,
    style_preferences: body.style || 'professionell und zugänglich',
    workflow_started: new Date().toISOString(),
    execution_id: $execution.id
  }
};

// n8n Cloud Version - Inline Style-Definition
