// Parse Strategy mit Markdown-Bereinigung
let response = $input.item.json.message?.content || $input.item.json.text || '{}';

// Entferne Markdown-Code-Blöcke (```json ... ```)
response = response.replace(/```json\s*/g, '').replace(/```\s*$/g, '').trim();

// Versuche JSON zu parsen
let data;
try {
  data = JSON.parse(response);
} catch (e) {
  // Fallback: Versuche, das erste JSON-Objekt zu extrahieren
  const jsonMatch = response.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    data = JSON.parse(jsonMatch[0]);
  } else {
    throw new Error(`❌ Konnte JSON nicht parsen: ${e.message}\n\nResponse:\n${response}`);
  }
}

const strategy = data.content_strategy;

return {
  json: {
    ...$('Load mitNORM Style').item.json,
    title: strategy.title,
    meta_description: strategy.meta_description,
    seo: {
      main_keyword: strategy.main_keyword,
      secondary_keywords: strategy.secondary_keywords,
      longtail_keywords: strategy.longtail_keywords
    },
    outline: strategy.outline,
    target_audience: strategy.target_audience
  }
};

// Parse Content & Extract Image Prompts
const response = $input.item.json.message?.content || $input.item.json.text || '';
const blogContent = response.trim();

// Extrahiere Bild-Platzhalter
const imageMatches = [...blogContent.matchAll(/\[BILD: (.+?)\]/g)];
const imagePrompts = imageMatches.map((match, i) => ({
  index: i,
  description: match[1],
  placeholder: match[0]
}));

// Filename
const today = new Date().toISOString().split('T')[0];
const slug = $('Load mitNORM Style').item.json.title
  .toLowerCase()
  .replace(/[äöü]/g, c => ({ä:'ae',ö:'oe',ü:'ue'}[c]||c))
  .replace(/ß/g, 'ss')
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-|-$/g, '')
  .substring(0, 60);

console.log(`📝 Blog: ${blogContent.split(/\s+/).length} Wörter, ${imagePrompts.length} Bilder`);

return {
  json: {
    ...$('Parse Strategy').item.json,
    blog_content: blogContent,
    filename_base: `${today}_${slug}`,
    image_prompts: imagePrompts,
    word_count: blogContent.split(/\s+/).length
  }
};

