// Extract Task ID
const response = $input.item.json;

if (response.code !== 200 || !response.data?.taskId) {
  throw new Error(`Grok Imagine Task fehlgeschlagen: ${response.message}`);
}

const taskId = response.data.taskId;
console.log(`🎨 Grok Imagine Task erstellt: ${taskId}`);

return {
  json: {
    ...$('Parse Content').item.json,
    grok_task_id: taskId,
    grok_task_created: new Date().toISOString()
  }
};

// Parse Grok Result
const response = $input.item.json;
const blogData = $('Parse Content').item.json;

// Parse Result JSON
const taskData = response.data;
const state = taskData.state;

// Wenn wir hier ankommen, garantiert der 'Check Status' Node, dass state === 'success' ist

// Extract Image URL
const resultJson = JSON.parse(taskData.resultJson || '{}');
const imageUrl = resultJson.resultUrls?.[0] || 'https://placehold.co/1792x1024';

console.log(`✅ Grok Imagine erfolgreich: ${imageUrl}`);

// Merge Image into Content
let blogContent = blogData.blog_content;

if (blogData.image_prompts.length > 0) {
  // Ersetze erstes Bild
  blogContent = blogContent.replace(
    blogData.image_prompts[0].placeholder,
    `![Cover Image](${imageUrl})`
  );

  // Entferne restliche Platzhalter
  for (let i = 1; i < blogData.image_prompts.length; i++) {
    blogContent = blogContent.replace(blogData.image_prompts[i].placeholder, '');
  }
}

return {
  json: {
    ...blogData,
    blog_content: blogContent,
    cover_image_url: imageUrl,
    images_generated: 1,
    grok_cost_time: taskData.costTime,
    grok_credits_consumed: taskData.consumeCredits
  }
};

// Parse Quality Score mit Markdown-Bereinigung
let response = $input.item.json.message?.content || $input.item.json.text || '{}';

// Entferne Markdown-Code-Blöcke
response = response.replace(/```json\s*/g, '').replace(/```\s*$/g, '').trim();

// Versuche JSON zu parsen
let quality;
try {
  quality = JSON.parse(response);
} catch (e) {
  // Fallback
  const jsonMatch = response.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    quality = JSON.parse(jsonMatch[0]);
  } else {
    throw new Error(`❌ Konnte Quality JSON nicht parsen: ${e.message}`);
  }
}

console.log(`📊 Quality: ${quality.total_score}/100 (${quality.grade})`);

return {
  json: {
    ...$('Merge Grok Image into Content').item.json,
    quality: quality
  }
};

// Final Response
const inputData = $('Parse Input').item.json;

const summary = {
  success: true,
  status: '✅ Blog erfolgreich erstellt mit Grok Imagine',
  execution_id: inputData.execution_id,
  timestamp: new Date().toISOString(),

  blog: {
    title: $json.title,
    filename: $json.filename_base,
    word_count: $json.word_count
  },

  quality: {
    total_score: $json.quality.total_score,
    grade: $json.quality.grade,
    feedback: $json.quality.feedback
  },

  seo: {
    main_keyword: $json.seo.main_keyword,
    secondary_keywords: $json.seo.secondary_keywords,
    target_audience: $json.target_audience
  },

  media: {
    cover_image_url: $json.cover_image_url,
    images_generated: $json.images_generated,
    image_fallback: $json.image_fallback || false,
    grok_credits_consumed: $json.grok_credits_consumed || 0
  },

  content: {
    markdown: $json.blog_content
  }
};

console.log('\n' + '='.repeat(70));
console.log('✅ BLOG MIT GROK IMAGINE ERSTELLT!');
console.log('='.repeat(70));
console.log(`📝 Titel: ${summary.blog.title}`);
console.log(`📊 Score: ${summary.quality.total_score}/100 (${summary.quality.grade})`);
console.log(`📄 Wörter: ${summary.blog.word_count}`);
console.log(`🎨 Grok Credits: ${summary.media.grok_credits_consumed}`);
console.log('='.repeat(70) + '\n');

return { json: summary };
